/* MatheQuest – ohne Build-Schritt, Backend oder Netzwerkanfragen. */
(() => {
'use strict';
const D = window.MQ_DOMAINS, CORE = window.MQ_QUESTIONS, FINAL = window.MQ_FINAL_QUESTIONS;
const Q = [...CORE,...FINAL];
const questionById = Object.fromEntries(Q.map(q => [q.id,q]));
const skills = D.flatMap(d => d.skills.map(s => ({...s,domain:d.id})));
const skillById = Object.fromEntries(skills.map(s => [s.id,s]));
const domainById = Object.fromEntries(D.map(d => [d.id,d]));
const KEY='mathequest.v1', MAX_SESSIONS=5000;
const $=s=>document.querySelector(s);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const button=(text,action,cls='',more='')=>`<button class="btn ${cls}" data-action="${action}" ${more}>${text}</button>`;
const percent=(n,d)=>d?Math.round(100*n/d):0;
const date=d=>new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'short',year:'numeric',timeZone:'Europe/Berlin'}).format(new Date(d));
const fresh=()=>({app:'MatheQuest',version:1,sessions:[],active:null,oral:{}});
let state=fresh(), storageFailed=false, saveError='', tabDomain='analysis', solutionsOpen=false, solutionFilter='all', solutionSearch='', solutionsPromise=null, pendingImport=null;
const labels={dashboard:'Weltkarte',training:'Training',skills:'Kompetenzlandkarte',progress:'Mein Fortschritt',achievements:'Erfolge',solutions:'Lernmodus',settings:'Einstellungen & Daten',quiz:'Training',report:'Ergebnisbericht'};
function validAnswer(a){return a===null||Number.isInteger(a)&&a>=0&&a<=2;}
function validPool(mode,ids){return mode==='final'?ids.length===9&&ids.every(id=>FINAL.some(q=>q.id===id)):ids.every(id=>CORE.some(q=>q.id===id));}
function validate(raw){
 if(!raw||raw.app!=='MatheQuest'||raw.version!==1||!Array.isArray(raw.sessions)||raw.sessions.length>MAX_SESSIONS)throw Error('Die Datei ist kein unterstützter MatheQuest-Lernstand (Version 1).');
 const result=fresh(), seen=new Set();
 for(const s of raw.sessions){
  if(!s||typeof s.id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(s.id)||seen.has(s.id)||!Number.isFinite(Date.parse(s.date))||!['diagnostic','domain','skill','final'].includes(s.mode)||typeof s.title!=='string'||s.title.length>150||!Array.isArray(s.ids)||!s.ids.length||s.ids.length>50||new Set(s.ids).size!==s.ids.length||s.ids.some(id=>typeof id!=='string'||!Object.hasOwn(questionById,id))||!Array.isArray(s.answers)||s.answers.length!==s.ids.length||!s.answers.every(validAnswer)||!validPool(s.mode,s.ids))throw Error('Ungültige Trainingseinheit. Die vorhandenen Daten wurden nicht verändert.');
  seen.add(s.id);result.sessions.push({id:s.id,date:new Date(s.date).toISOString(),mode:s.mode,title:s.title,ids:[...s.ids],answers:[...s.answers]});
 }
 if(raw.oral&&typeof raw.oral==='object'&&!Array.isArray(raw.oral))for(const [qid,value]of Object.entries(raw.oral)){if(Object.hasOwn(questionById,qid)&&['yes','partial','no'].includes(value))result.oral[qid]=value;}
 if(raw.active){const a=raw.active;
  if(!Array.isArray(a.ids)||!a.ids.length||a.ids.length>50||a.ids.some(id=>typeof id!=='string'||!Object.hasOwn(questionById,id))||new Set(a.ids).size!==a.ids.length||!Array.isArray(a.answers)||a.answers.length!==a.ids.length||!a.answers.every(validAnswer)||!Number.isInteger(a.index)||a.index<0||a.index>=a.ids.length||!['diagnostic','domain','skill','final'].includes(a.mode)||typeof a.title!=='string'||a.title.length>150||!Number.isFinite(Date.parse(a.startedAt))||!validPool(a.mode,a.ids))throw Error('Das gespeicherte laufende Training ist ungültig.');
  result.active={ids:[...a.ids],answers:[...a.answers],index:a.index,mode:a.mode,title:a.title,startedAt:new Date(a.startedAt).toISOString()};
 }
 return result;
}
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));}catch(e){storageFailed=true;saveError='Der gespeicherte Lernstand konnte nicht gelesen werden. Er wurde nicht überschrieben. Exportiere neue Ergebnisse, bevor du diese Seite schließt.';}
function save(){try{if(saveError)return false;localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;return true;}catch(e){storageFailed=true;return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function loadSolutions(){
 if(window.MQ_SOLUTIONS)return Promise.resolve(window.MQ_SOLUTIONS);
 if(!solutionsPromise)solutionsPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='solutions.js';script.onload=()=>window.MQ_SOLUTIONS?resolve(window.MQ_SOLUTIONS):reject(Error('Der Lösungsschlüssel ist ungültig.'));script.onerror=()=>{solutionsPromise=null;script.remove();reject(Error('solutions.js konnte nicht geladen werden. Bitte prüfe, ob alle Projektdateien im selben Ordner liegen.'));};document.head.append(script);});
 return solutionsPromise;
}
function shuffle(array){const a=[...array];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
const level=xp=>Math.min(60,1+Math.floor(xp/50));
function compute(){
 const histories={}, reports={};let xp=0,totalCorrect=0,totalAnswered=0;
 const key=window.MQ_SOLUTIONS;
 for(const s of state.sessions){let score=0,earned=0;const byDomain={},bySkill={};
  s.ids.forEach((id,i)=>{const q=questionById[id],answer=s.answers[i],answered=answer!==null,correct=!!key&&answered&&answer===key[id].correct;
   if(!histories[id])histories[id]={attempts:0,correct:0,xp:0,latest:false,sessions:new Set()};
   const h=histories[id];
   for(const [group,name]of [[byDomain,q.domain],[bySkill,q.skill]]){if(!group[name])group[name]={total:0,correct:0,answered:0};group[name].total++;if(answered)group[name].answered++;if(correct)group[name].correct++;}
   if(correct){const reward=s.mode==='final'?0:Math.min(h.attempts===0?10:5,20-h.xp);h.xp+=reward;earned+=reward;h.correct++;score++;totalCorrect++;}
   if(answered){h.attempts++;h.latest=correct;h.sessions.add(s.id);totalAnswered++;}
  });
  xp+=earned;reports[s.id]={score,xp:earned,byDomain,bySkill,level:level(xp)};
 }
 const competency={};
 for(const s of skills){const ids=CORE.filter(q=>q.skill===s.id).map(q=>q.id), hs=ids.map(id=>histories[id]).filter(h=>h&&h.attempts>0);const unique=hs.length,correct=hs.filter(h=>h.latest).length,attempts=hs.reduce((sum,h)=>sum+h.attempts,0),hits=hs.reduce((sum,h)=>sum+h.correct,0),sessions=new Set(hs.flatMap(h=>[...h.sessions])).size;
  let status='untested';if(unique){status='uncertain';if(unique>=3&&correct/unique>=.6)status='partial';if(unique===5&&correct/unique>=.8&&hits/attempts>=.8&&sessions>=2)status='secure';}
  competency[s.id]={status,unique,correct,attempts,hits,rate:percent(hits,attempts),sessions};
 }
 return{histories,reports,xp,level:level(xp),totalCorrect,totalAnswered,competency,unique:CORE.filter(q=>histories[q.id]?.attempts>0).length};
}
let computed=compute();
function refresh(){computed=compute();$('#header-level').textContent=`Level ${computed.level}`;}
const statusNames={untested:'Nicht geprüft',uncertain:'Unsicher',partial:'Teilweise beherrscht',secure:'Sicher beherrscht'};
function statusBadge(value){return `<span class="status ${value}"><span class="live-dot" style="background:${{untested:'#81778c',uncertain:'#dfa97f',partial:'#94b3ed',secure:'#6ac5ae'}[value]};width:4px;height:4px"></span>${statusNames[value]}</span>`;}
function heading(title,subtitle,extra=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;}
function examNote(){return `<div class="exam-note">${icon('info')}<span>Für die Hamburger Oberstufe · Die konkrete Prüfungsrelevanz richtet sich nach deinem Unterricht und den offiziellen Vorgaben. XP zeigen deinen Einsatz; Kompetenz wird getrennt bewertet.</span></div>`;}
function progressBar(p){return `<div class="progress-track" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p}%"></span></div>`;}
const countryNames={
 analysis:['Termtal','Funktionsküste','Wurzelwald','Spiegelsteppe','Tangentenhain','Kettengebirge','Kurvenkönigreich','Integralinseln','Wachstumswüste','Modellhochland'],
 geometry:['Koordinatenkap','Vektorauen','Rechenebene','Distanzklippen','Winkelwald','Geradenpass','Kreuzungslande','Ebenenplateau','Schnittschlucht','Raumfestung'],
 probability:['Zufallsbucht','Chancenfelder','Pfadwald','Kombinationsküste','Bedingungsberge','Freilande','Variablental','Erwartungsauen','Binomialhügel','Testzitadelle']
};
const countryLevels=[1,6,12,18,24,30,36,42,48,55];
let selectedCountry='analysis-01';
function conquest(){
 const conquered=skills.filter(s=>computed.competency[s.id].status==='secure').length;
 const ready=conquered===30&&computed.level===60;
 const cleared=ready&&state.sessions.some(s=>s.mode==='final'&&computed.reports[s.id]?.score>=8);
 return{conquered,ready,cleared,total:conquered+(cleared?1:0)};
}
function countryState(id){return computed.competency[id].status==='secure'?'conquered':computed.competency[id].unique?'explored':'unknown';}
function worldSVG(){
 const c=conquest(),positions=[[58,208],[384,108],[706,272]];
 const hash=(a,b)=>(Math.sin(a*127.1+b*311.7)*43758.5453)%1;
 let lands='';
 D.forEach((domain,di)=>{
  const [ox,oy]=positions[di],verts=Array.from({length:5},(_,r)=>Array.from({length:4},(_,col)=>[ox+col*76+hash(r+di*6,col)*13,oy+r*65+hash(col+di*9,r)*12]));
  function edge(a,b){if(a[0]>b[0]||(a[0]===b[0]&&a[1]>b[1]))[a,b]=[b,a];const dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy),mid=[(a[0]+b[0])/2,(a[1]+b[1])/2];const jitter=hash(mid[0],mid[1])*6;return[mid[0]-dy/len*jitter,mid[1]+dx/len*jitter];}
  let n=0;
  for(let r=0;r<4;r++)for(let col=0;col<3;col++){
   if((r===0&&col===0)||(r===3&&col===2))continue;
   const i=n++,skill=domain.skills[i],v=[verts[r][col],verts[r][col+1],verts[r+1][col+1],verts[r+1][col]],points=v.flatMap((a,j)=>[a,edge(a,v[(j+1)%4])]).map(p=>p.join(',')).join(' ');
   const cx=v.reduce((sum,p)=>sum+p[0],0)/4,cy=v.reduce((sum,p)=>sum+p[1],0)/4,st=countryState(skill.id);
   lands+=`<g class="map-country ${domain.id} ${st} ${selectedCountry===skill.id?'selected':''}" role="button" tabindex="0" data-action="select-country" data-skill="${skill.id}" aria-label="${countryNames[domain.id][i]}: ${skill.name}, ${st==='conquered'?'erobert':st==='explored'?'erkundet':'unentdeckt'}, Richtlevel ${countryLevels[i]}" aria-pressed="${selectedCountry===skill.id}"><title>${countryNames[domain.id][i]} · ${skill.name} · Richtlevel ${countryLevels[i]}</title><polygon points="${points}"/><text class="country-number" x="${cx}" y="${cy-3}" text-anchor="middle">${st==='conquered'?'⚑':String(i+1).padStart(2,'0')}</text><text class="country-level" x="${cx}" y="${cy+14}" text-anchor="middle">LV ${countryLevels[i]}</text></g>`;
  }
  lands+=`<text class="continent-title ${domain.id}" x="${ox+110}" y="${oy-34}" text-anchor="middle">${domain.name.toUpperCase()}</text><text class="continent-subtitle" x="${ox+110}" y="${oy-15}" text-anchor="middle">${domain.skills.filter(s=>countryState(s.id)==='conquered').length} / 10 LÄNDER EROBERT</text>`;
 });
 return `<svg class="world-map" viewBox="0 0 1100 655" xmlns="http://www.w3.org/2000/svg" aria-labelledby="world-title world-desc"><title id="world-title">Die Welt von MatheQuest</title><desc id="world-desc">Drei Kontinente mit je zehn anklickbaren Ländern. Goldene Flaggen markieren sichere Kompetenzen. Die Zitadelle ist das Abschlussgebiet auf Level 60.</desc><defs><pattern id="sea-dots" width="26" height="26" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#7c7991" opacity=".18"/></pattern><radialGradient id="world-sea"><stop stop-color="#242335"/><stop offset="1" stop-color="#15151f"/></radialGradient><filter id="coast-shadow" x="-40%" y="-40%" width="180%" height="180%"><feDropShadow dx="0" dy="7" stdDeviation="7" flood-color="#000" flood-opacity=".35"/></filter></defs><rect width="1100" height="655" rx="12" fill="url(#world-sea)"/><rect width="1100" height="655" rx="12" fill="url(#sea-dots)"/>
 <g class="sea-routes"><path d="M236 491C360 570 338 336 419 335M605 356C645 387 671 442 755 454M905 280C987 262 1010 232 1002 174"/><circle cx="338" cy="460" r="4"/><circle cx="663" cy="404" r="4"/></g>
 <g class="compass" transform="translate(87 88)"><circle r="30"/><circle r="23"/><path d="M0-39V39M-39 0h78M-17-17 17 17M-17 17 17-17"/><path class="compass-needle" d="M0-25 6 0 0 25-6 0Z"/><text y="-48" text-anchor="middle">N</text></g>
 <text class="ocean-label" x="250" y="86">DAS MEER DER MÖGLICHKEITEN</text>
 ${lands}
 <g class="map-country final-country ${c.cleared?'conquered':c.ready?'ready':'locked'} ${selectedCountry==='final'?'selected':''}" role="button" tabindex="0" data-action="select-country" data-skill="final" aria-pressed="${selectedCountry==='final'}" aria-label="Zitadelle der Meisterschaft, Level 60, ${c.cleared?'erobert':c.ready?'freigeschaltet':'noch gesperrt'}"><title>Zitadelle der Meisterschaft · Level 60</title><polygon points="939,82 971,60 1002,71 1040,59 1065,95 1051,128 1060,154 1025,174 991,164 963,182 940,151 948,118"/><path class="citadel-drawing" d="M975 129V102h11v8h10V91h11v19h10v-8h11v27h-53m21 0v-12h11v12M996 91V77l15 5-15 5"/><text class="country-level" x="1002" y="151" text-anchor="middle">${c.cleared?'⚑ EROBERT':'LEVEL 60'}</text></g><text class="final-title" x="1000" y="210" text-anchor="middle">DIE ZITADELLE</text><text class="continent-subtitle" x="1000" y="229" text-anchor="middle">DEINE LETZTE EROBERUNG</text>
 <g class="map-mountains" transform="translate(360 562)"><path d="m0 22 15-25 15 25m-7 0 23-42 23 42m-32-26 9 8 5-6m-9 24 18-30 18 30"/></g><text class="ocean-label" x="94" y="570">DER HORIZONT GEHÖRT DIR.</text><text class="world-caption" x="1050" y="619" text-anchor="end">MATHEQUEST · ATLAS DES WISSENS</text></svg>`;
}
function countryPanel(){
 const c=conquest();
 if(selectedCountry==='final')return `<div id="country-panel-anchor" class="country-panel final-panel" tabindex="-1" aria-live="polite"><div class="eyebrow">DAS ABSCHLUSSGEBIET · LEVEL 60</div><div class="country-panel-title">${icon('trophy')}<h3>Zitadelle der Meisterschaft</h3></div><p>Neun anspruchsvolle Aufgaben aus allen drei Gebieten: Optimierung, räumliche Geometrie, Bayes und Hypothesentests. Erobere die Zitadelle mit mindestens 8 von 9 richtigen Antworten.</p><div class="citadel-requirements"><span class="${computed.level===60?'met':''}">${icon(computed.level===60?'check':'shield')} Level 60 · aktuell ${computed.level}</span><span class="${c.conquered===30?'met':''}">${icon(c.conquered===30?'check':'shield')} ${c.conquered}/30 Länder sicher beherrscht</span></div>${c.cleared?'<div class="conquest-notice">⚑ Die Welt gehört dir. Alle 31 Gebiete sind erobert!</div>':''}${button(c.cleared?'Zitadelle erneut spielen':c.ready?'Zitadelle herausfordern':'Noch nicht freigeschaltet','start-final','btn-primary',c.ready?'':'disabled')}<small>Keine zusätzlichen XP. Hier entscheidet dein Wissen.</small></div>`;
 const skill=skillById[selectedCountry],di=domainById[skill.domain].skills.findIndex(s=>s.id===skill.id),st=countryState(skill.id),comp=computed.competency[skill.id];
 return `<div id="country-panel-anchor" class="country-panel" tabindex="-1" aria-live="polite"><div class="eyebrow">${domainById[skill.domain].name.toUpperCase()} · LAND ${String(di+1).padStart(2,'0')} · RICHTLEVEL ${countryLevels[di]}</div><div class="country-panel-title"><span class="country-crest ${st}">${st==='conquered'?'⚑':'◇'}</span><div><h3>${countryNames[skill.domain][di]}</h3><span>${skill.name}</span></div><span class="country-tag ${st}">${st==='conquered'?'Erobert':st==='explored'?'Erkundet':'Unentdeckt'}</span></div><ul class="country-subskills">${skill.subskills.map(sub=>`<li>${sub.name}</li>`).join('')}</ul><div class="country-evidence"><span>${comp.unique}/5 Aufgaben entdeckt</span><span>${comp.attempts?comp.rate+' % Trefferquote':'Noch kein Versuch'}</span><span>${Math.min(comp.sessions,2)}/2 nötige Einheiten</span></div><p class="country-rule">${st==='conquered'?'Flagge gesetzt! Festige dein Wissen, damit das Land sicher bleibt.':'Zum Erobern: alle 5 Aufgaben bearbeiten, mindestens 80 % aktuelle und gesamte Trefferquote, mindestens 2 Einheiten. Richtlevel sind Empfehlungen – du kannst direkt üben.'}</p>${button(`${st==='conquered'?'Land sichern':'Land erkunden'} ${icon('arrow')}`,'start-skill','btn-primary',`data-skill="${skill.id}"`)}</div>`;
}
function worldSection(){const c=conquest();return `<section class="world-section" aria-label="Eroberbare Weltkarte"><div class="world-heading"><div><div class="eyebrow">DEIN ABENTEUER HAT EIN ZIEL</div><h2>Erobere die Welt des Wissens.</h2><p>Drei Kontinente. Dreißig Länder. Eine letzte Zitadelle.</p></div><div class="conquest-counter"><strong>${c.total}<span>/31</span></strong><small>GEBIETE EROBERT</small></div></div><div class="world-frame">${worldSVG()}</div><div class="map-legend"><span><i class="unknown"></i>Unentdeckt</span><span><i class="explored"></i>Erkundet</span><span><i class="conquered"></i>⚑ Erobert</span><span><i class="locked"></i>Level-60-Zitadelle</span><small>Wähle ein Land auf der Karte.</small></div>${countryPanel()}</section>`;}

function domainArt(id){
 const grid='<g opacity=".1"><path d="M0 20h240M0 45h240M0 70h240M30 0v90M65 0v90M100 0v90M135 0v90M170 0v90M205 0v90"/></g>';
 const art={analysis:`${grid}<path opacity=".35" d="M9 72h220M49 87V4"/><path d="M17 24c28 65 61 68 89 17S164-9 213 33" stroke-width="2"/><path d="m113 79 66-68" stroke-dasharray="3 5" opacity=".45"/><circle cx="148" cy="43" r="3" fill="currentColor" stroke="none"/><text x="184" y="79" fill="currentColor" stroke="none" font-size="15" font-family="Georgia" font-style="italic" opacity=".7">ƒ′(x)</text>`,geometry:`${grid}<path opacity=".3" d="m121 84 0-77m0 65-76-32m76 32 77-32"/><path d="m121 16 56 25v30l-56 25-56-25V41Z" stroke-width="1.6" transform="translate(0 -7)"/><path d="m65 34 56 26 56-26m-56 26v29" stroke-width="1.6"/><path d="m65 64 56-25 56 25m-56-25V9" stroke-dasharray="3 4" opacity=".35"/><circle cx="177" cy="34" r="3" fill="currentColor" stroke="none"/><path d="m26 69 29-14m-7-1 7 1-3 6" opacity=".6"/>`,probability:`${grid}<path opacity=".3" d="M11 79h220"/><path d="M14 77c38 0 47-4 62-35S98 9 120 9s28 4 44 35 30 33 62 33" stroke-width="1.8"/><path d="M70 77V55m15 22V32m15 45V18m15 59V10m15 67V11m15 66V23m15 54V43m15 34V65" opacity=".25" stroke-width="8"/><circle cx="120" cy="9" r="3" fill="currentColor" stroke="none"/><text x="193" y="25" fill="currentColor" stroke="none" font-size="14" font-family="Georgia" font-style="italic" opacity=".6">P(X)</text>`};
 return `<svg class="domain-art" viewBox="0 0 240 100" aria-hidden="true">${art[id]}</svg>`;
}
function domainCard(d){const attempted=CORE.filter(q=>q.domain===d.id&&computed.histories[q.id]?.attempts>0).length;const secure=d.skills.filter(s=>computed.competency[s.id].status==='secure').length;const symbols={analysis:'ƒ',geometry:'◇',probability:'∑'};
 return `<a href="#training" class="domain-card ${d.id}" data-action="start-domain" data-domain="${d.id}"><div class="domain-topline"><span class="domain-symbol">${symbols[d.id]}</span><span>${{analysis:'01',geometry:'02',probability:'03'}[d.id]} / WISSENSGEBIET</span></div>${domainArt(d.id)}<h3>${d.name}</h3><p>${d.description}</p><div class="domain-meta"><span>${icon('tree')}10 Kompetenzen</span><span>${icon('book')}50 Aufgaben</span></div><div class="domain-progress"><span>${attempted} von 50 Aufgaben erkundet</span><span>${secure}/10 sicher</span></div><div class="country-chips" aria-label="Länderstatus">${d.skills.map(s=>`<span class="${countryState(s.id)}" title="${s.name}: ${countryState(s.id)==='conquered'?'erobert':'noch nicht erobert'}">${countryState(s.id)==='conquered'?'⚑':'◇'}</span>`).join('')}</div><div class="card-cta">Gebiet erkunden ${icon('arrow')}</div></a>`;
}
function stats(){const c=computed;return `<div class="stats-grid"><div class="stat level-stat"><div class="level-emblem">${c.level}</div><div class="level-info"><strong>${c.level===60?'Mathe-Legende':c.level===1?'Dein Abenteuer beginnt':'Dein Wissen wächst'}</strong><div class="xp-numbers"><span>${c.level===60?'Maximallevel erreicht':`${c.xp%50} / 50 XP`}</span><span>LEVEL ${c.level}</span></div><div class="level-countries">${conquest().conquered}/30 Länder erobert · Ziel: Level 60</div></div></div><div class="stat"><div class="stat-label">${icon('check')}Aufgaben bearbeitet</div><div class="stat-value">${c.unique}<small>/ 150</small></div><div class="stat-caption">Jede neue Frage bringt dich weiter.</div></div><div class="stat"><div class="stat-label">${icon('target')}Deine Trefferquote</div><div class="stat-value">${c.totalAnswered?percent(c.totalCorrect,c.totalAnswered)+'%':'–'}<small>${c.totalAnswered?'richtig':'noch offen'}</small></div><div class="stat-caption">${c.totalAnswered?`${c.totalCorrect} von ${c.totalAnswered} Antworten richtig`:'Starte dein erstes Training.'}</div></div><div class="stat"><div class="stat-label">${icon('trophy')}Sichere Kompetenzen</div><div class="stat-value">${skills.filter(s=>c.competency[s.id].status==='secure').length}<small>/ 30</small></div><div class="stat-caption">Wissen wächst mit Wiederholung.</div></div></div>`;}
function previewSkills(){const weak=[...skills].sort((a,b)=>{const rank={uncertain:0,partial:1,untested:2,secure:3};return rank[computed.competency[a.id].status]-rank[computed.competency[b.id].status];});const selected=[];for(const d of D)selected.push(weak.find(s=>s.domain===d.id));return selected.map(s=>`<a class="skill-preview ${s.domain}" href="#skills" data-action="show-skill-domain" data-domain="${s.domain}"><span class="skill-small-icon">${{analysis:'ƒ',geometry:'◇',probability:'∑'}[s.domain]}</span><div><strong>${s.name}</strong><small>${domainById[s.domain].name} · ${computed.competency[s.id].unique}/5 Aufgaben</small></div>${statusBadge(computed.competency[s.id].status)}</a>`).join('');}
function dashboard(){const resumed=state.active;return `${heading('Bereit für dein nächstes Level?', 'Setze deine Flaggen. Erobere alle Länder. Erreiche die Zitadelle auf Level 60.',`<span class="date-label">${icon('clock')}${date(new Date())}</span>`)}${worldSection()}<div class="world-start"><span>${resumed?'Dein Training wartet auf dich.':'Wo beginnt deine Reise? Eine Diagnose zeigt dir deinen Ausgangspunkt.'}</span>${button(`${resumed?'Training fortsetzen':'Lernreise starten'} ${icon('arrow')}`,resumed?'resume':'start-diagnostic','btn-primary')}</div>${stats()}<section><div class="section-heading"><div><h2>Deine drei Kontinente</h2><p>Jedes Land steht für eine mathematische Kompetenz.</p></div><a class="text-link" href="#skills">Alle Kompetenzen ${icon('arrow')}</a></div><div class="domain-grid">${D.map(domainCard).join('')}</div></section>${examNote()}`;}

function training(){return `${heading('Dein Training. Dein Tempo.','Wähle, woran du heute wachsen möchtest.')} ${state.active?`<div class="info-box">Ein Training wartet auf dich: ${esc(state.active.title)} · ${state.active.answers.filter(a=>a!==null).length}/${state.active.ids.length} beantwortet. ${button('Fortsetzen','resume','btn-primary')}</div>`:''}<div class="training-options"><section class="panel training-feature diagnostic"><div class="quest-icon">${icon('target')}</div><div class="eyebrow">DER GROSSE ÜBERBLICK</div><h2>Standort bestimmen</h2><p>Eine Frage aus jedem Kompetenzbereich. Entdecke deine Stärken und finde heraus, was du als Nächstes üben kannst. Nach jeder Antwort bekommst du direkt Feedback. Den Gesamtbericht erhältst du nach der Abgabe.</p><div class="tag-line"><span>30 Fragen</span><span>Alle 3 Gebiete</span><span>ca. 15 Minuten</span></div>${button(`Diagnose starten ${icon('arrow')}`,'start-diagnostic','btn-primary')}</section><section class="panel training-feature"><div class="quest-icon">${icon('tree')}</div><div class="eyebrow">GEZIELT WEITERKOMMEN</div><h2>Eine Kompetenz vertiefen</h2><p>Von Potenzregeln bis zur Binomialverteilung: Übe genau das, was du gerade brauchst. Fünf kurze Fragen helfen dir, ein Konzept besser zu verstehen.</p><div class="tag-line"><span>5 Fragen je Skill</span><span>30 Kompetenzen</span></div><a class="btn" href="#skills">Skill auswählen ${icon('arrow')}</a></section></div><div class="section-heading"><div><h2>Ein ganzes Gebiet erkunden</h2><p>10 Fragen pro Training, eine aus jedem Bereich.</p></div></div><div class="domain-grid">${D.map(domainCard).join('')}</div>${examNote()}`;}
function skillMap(){const d=domainById[tabDomain];return `${heading('Deine Kompetenzlandkarte','30 Kompetenzen, 90 Teilkompetenzen – und dein ganz persönlicher Weg.')}<div class="info-box">Kompetenz ist mehr als XP. „Sicher“ erfordert alle 5 unterschiedlichen Aufgaben, mindestens 80 % aktuelle und gesamte Trefferquote sowie mindestens 2 abgeschlossene Einheiten. Multiple Choice bleibt ein Indikator; Begründen übst du zusätzlich mit deiner Lehrkraft.</div><div class="filter-tabs" role="group" aria-label="Fachgebiet">${D.map(x=>`<button class="${x.id===tabDomain?'active':''}" data-action="skill-tab" data-domain="${x.id}">${x.name}</button>`).join('')}</div><div class="skill-tree">${d.skills.map((s,i)=>{const c=computed.competency[s.id];return `<details class="skill-node"><summary>${icon('chevron','chev')}<span class="skill-index">${String(i+1).padStart(2,'0')}</span><strong>${s.name}</strong>${statusBadge(c.status)}</summary><div class="skill-detail"><div><ul class="subskill-list">${s.subskills.map(sub=>`<li>${sub.name}</li>`).join('')}</ul><p class="skill-summary" style="margin-top:15px;margin-bottom:0">${c.unique}/5 verschiedene Aufgaben · <strong>${c.hits}/${c.attempts}</strong> richtige Antworten · ${c.attempts?c.rate+' %':'noch keine'} Trefferquote<br>Wiederholung: ${c.status==='secure'?'zur Festigung empfohlen':c.status==='untested'?'zuerst Standort bestimmen':'empfohlen'}</p></div>${button(`Skill trainieren ${icon('arrow')}`,'start-skill','',`data-skill="${s.id}"`)}</div></details>`;}).join('')}</div><div class="legend">${Object.keys(statusNames).map(statusBadge).join('')}</div><p class="storage-note">Die mündliche Einschätzung wird im Lernmodus separat gespeichert und verändert die Multiple-Choice-Quote nicht.</p>${examNote()}`;}
function makeSession(mode,value){let qs,title;if(mode==='final'){qs=shuffle(FINAL);title='Zitadelle · Level-60-Herausforderung';}else if(mode==='diagnostic'){qs=shuffle(skills.map(s=>shuffle(CORE.filter(q=>q.skill===s.id))[0]));title='Diagnose · Alle Wissensgebiete';}else if(mode==='domain'){qs=shuffle(domainById[value].skills.map(s=>shuffle(CORE.filter(q=>q.skill===s.id))[0]));title=`Gebietstraining · ${domainById[value].name}`;}else{qs=shuffle(CORE.filter(q=>q.skill===value));title=`Skill · ${skillById[value].name}`;}return{mode,title,ids:qs.map(q=>q.id),answers:qs.map(()=>null),index:0,startedAt:new Date().toISOString()};}
function start(mode,value){if(mode==='final'&&!conquest().ready){toast('Erreiche Level 60 und erobere zuerst alle 30 Länder.');return;}const proceed=()=>{state.active=makeSession(mode,value);save();location.hash='quiz';render();};if(state.active){showDialog('Neues Training starten?',`<p>Dein laufendes Training „${esc(state.active.title)}“ wird dadurch ersetzt. Die bisherigen Antworten dieses Trainings wurden noch nicht ausgewertet.</p><div class="button-row">${button('Fortsetzen','resume','btn-primary')}${button('Neues Training','confirm-start','',`data-mode="${mode}" data-value="${value||''}"`)}</div>`);}else proceed();}
function quiz(){
 const a=state.active;if(!a){location.hash='training';return '';}
 const q=questionById[a.ids[a.index]],chosen=a.answers[a.index],answered=a.answers.filter(x=>x!==null).length;
 const solution=chosen!==null?window.MQ_SOLUTIONS?.[q.id]:null;
 const isCorrect=solution&&chosen===solution.correct;
 const feedback=solution?`<div id="answer-feedback" class="answer-feedback ${isCorrect?'correct':'incorrect'}" role="status" tabindex="-1"><strong>${icon(isCorrect?'check':'close')}${isCorrect?'Richtig!':'Noch nicht richtig.'}</strong>${!isCorrect?`<p class="feedback-answer">Richtige Antwort: <b>${esc(q.options[solution.correct])}</b></p>`:''}<p>${esc(solution.explanation)}</p><small>Deine erste Antwort zählt. Du kannst jetzt zur nächsten Frage weitergehen.</small></div>`:'';
 return `<div class="quiz-wrap"><div class="quiz-topline"><span>${esc(a.title)}</span><a href="#training" class="text-link">Später fortsetzen ${icon('close')}</a></div><div class="quiz-progress"><div class="quiz-progress-text"><span>Frage ${a.index+1} von ${a.ids.length}</span><span>${answered} beantwortet</span></div>${progressBar(percent(answered,a.ids.length))}</div><section class="question-card"><div class="question-meta"><span class="tag">${domainById[q.domain].name}</span><span>${skillById[q.skill].name}</span><span>· ${q.difficulty===1?'Grundlagen':q.difficulty===3?'Meisterprüfung · Level 60':'Nächster Schritt'}</span></div><h1 class="question-title">${esc(q.prompt)}</h1><div class="answer-options" role="group" aria-label="Antwort auswählen">${q.options.map((option,i)=>{
  const correct=solution&&i===solution.correct,wrong=solution&&i===chosen&&!isCorrect;
  return `<button class="answer-option ${chosen===i?'selected':''} ${correct?'answer-correct':''} ${wrong?'answer-incorrect':''}" aria-pressed="${chosen===i}" data-action="answer" data-answer="${i}" ${chosen!==null?'disabled':''}><span class="answer-key">${'ABC'[i]}</span><span>${esc(option)}</span>${correct?`<span class="answer-result">${icon('check')}Richtig</span>`:wrong?`<span class="answer-result">${icon('close')}Deine Antwort</span>`:''}</button>`;
 }).join('')}</div>${feedback}<p class="question-note">${icon('shield')}${chosen===null?'Nach deiner Auswahl siehst du sofort die Lösung. Deine erste Antwort zählt.':'Antwort gespeichert. Punkte und XP erhältst du nach dem Abschließen.'}</p></section><div class="quiz-nav">${button('Zurück','quiz-prev','btn-ghost',a.index===0?'disabled':'')}<div style="display:flex;gap:8px">${a.index<a.ids.length-1?button(`Weiter ${icon('arrow')}`,'quiz-next',''):''}${button('Abschließen','submit','btn-primary')}</div></div><div class="question-dots" role="group" aria-label="Fragenübersicht">${a.ids.map((id,i)=>`<button class="${a.answers[i]!==null?'answered':''} ${a.index===i?'current':''}" data-action="quiz-jump" data-index="${i}" aria-label="Frage ${i+1}, ${a.answers[i]===null?'unbeantwortet':'beantwortet'}" ${i===a.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><div class="quiz-save-note">${answered===a.ids.length?'Alle Fragen beantwortet. Bereit für deine Auswertung?':`${a.ids.length-answered} unbeantwortet · Bereits beantwortete Fragen kannst du mit Erklärung erneut ansehen.`}</div></div>`;
}
function showDialog(title,content){$('#modal-content').innerHTML=`<div class="dialog-content"><h2>${title}</h2>${content}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function closeDialog(){if($('#modal').open)$('#modal').close();}
async function submit(confirmed=false){const a=state.active;if(!a||submit.busy)return;const missing=a.answers.flatMap((v,i)=>v===null?[i+1]:[]);if(missing.length&&!confirmed){showDialog('Noch nicht ganz fertig',`<p>${missing.length} Frage${missing.length===1?' ist':'n sind'} noch unbeantwortet: ${missing.join(', ')}. Unbeantwortete Fragen zählen im Ergebnis als falsch und geben keine XP.</p><div class="button-row">${button('Weiter üben','close-dialog','btn-primary')}${button('Trotzdem abgeben','confirm-submit')}</div>`);return;}
 submit.busy=true;closeDialog();try{await loadSolutions();if(state.active!==a)return;refresh();const before=computed.level;const s={id:crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random().toString(36).slice(2),date:new Date().toISOString(),mode:a.mode,title:a.title,ids:[...a.ids],answers:[...a.answers]};state.sessions.push(s);state.active=null;refresh();save();location.hash=`report/${s.id}`;render();if(computed.level>before){$('#level-up').innerHTML=`<small>LEVELAUFSTIEG</small><strong>Level ${computed.level}</strong><span>Deine Übung zahlt sich aus.</span>`;$('#level-up').classList.add('visible');setTimeout(()=>$('#level-up').classList.remove('visible'),3500);}}catch(e){toast(e.message);}finally{submit.busy=false;}}
function summaryTable(groups,type){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>${type==='domain'?'Wissensgebiet':'Kompetenzbereich'}</th><th>Richtig</th><th>Quote</th><th>Empfehlung</th></tr></thead><tbody>${Object.entries(groups).map(([id,g])=>`<tr><td>${type==='domain'?domainById[id].name:skillById[id].name}</td><td>${g.correct} / ${g.total}</td><td>${percent(g.correct,g.total)} %</td><td>${g.correct===g.total?'Weiter festigen':'Wiederholen'}</td></tr>`).join('')}</tbody></table></div>`;}
function report(id){const s=state.sessions.find(s=>s.id===id);if(!s)return `${heading('Bericht nicht gefunden','Diese Trainingseinheit ist auf diesem Gerät nicht gespeichert.')}<a class="btn" href="#progress">Zum Fortschritt</a>`;const r=computed.reports[id],wrong=s.ids.filter((qid,i)=>s.answers[i]!==window.MQ_SOLUTIONS[qid].correct),weak=Object.entries(r.bySkill).filter(([id,g])=>g.correct<g.total);return `${heading('Ein Schritt weiter.','Dein Training ist abgeschlossen. Hier siehst du, was schon sitzt.',`<a class="text-link no-print" href="#progress">Alle Einheiten ${icon('arrow')}</a>`)}<div class="print-only"><p>MatheQuest · ${esc(s.title)} · ${date(s.date)} · Bericht ${s.id}</p></div><section class="panel report-hero"><div class="score-ring" style="--score:${percent(r.score,s.ids.length)}%"><div><strong>${percent(r.score,s.ids.length)} %</strong><small>RICHTIG</small></div></div><div><div class="eyebrow">${esc(s.title)}</div><h2>${r.score===s.ids.length?'Alles richtig. Stark gelernt!':r.score>=s.ids.length*.6?'Eine gute Grundlage.':'Dein Ausgangspunkt ist gefunden.'}</h2><p>${r.score} von ${s.ids.length} Aufgaben richtig · ${date(s.date)}</p></div><div class="report-rewards"><strong>+${r.xp} XP</strong><small>Level nach Abgabe: ${r.level}<br>Aktuell: Level ${computed.level}</small></div></section><div class="button-row no-print" style="margin:0 0 25px">${button(`${icon('down')}Bericht als JSON`,'export-report','',`data-session="${id}"`)}${button('Bericht drucken / PDF','print')}${button('Lösungen freigeben','unlock-solutions','btn-ghost')}</div><section class="panel"><h2>Dein Ergebnis im Detail</h2>${summaryTable(r.byDomain,'domain')}<h3 style="margin-top:25px">Kompetenzbereiche</h3>${summaryTable(r.bySkill,'skill')}</section><section class="panel" style="margin-top:20px"><h2>${weak.length?'Das lohnt sich zu wiederholen':'Wissen behalten'}</h2><p style="font-size:11px;margin-top:8px">${weak.length?'Diese Bereiche verdienen beim nächsten Training etwas Aufmerksamkeit.':'Wiederhole die Aufgaben mit etwas Abstand und erkläre deinen Rechenweg laut.'}</p><div class="recommendations no-print">${weak.length?weak.map(([sid])=>button(`${skillById[sid].name} ${icon('arrow')}`,'start-skill','',`data-skill="${sid}"`)).join(''):'<a class="btn" href="#skills">Zur Kompetenzlandkarte</a>'}</div></section><section class="panel" style="margin-top:20px"><h2>Falsch oder unbeantwortet <span class="muted">(${wrong.length})</span></h2>${wrong.length?wrong.map(qid=>{const q=questionById[qid],a=s.answers[s.ids.indexOf(qid)];return `<div class="history-row"><div><strong>${esc(q.prompt)}</strong><small>${qid} · Deine Antwort: ${a===null?'Nicht beantwortet':esc(q.options[a])}</small></div></div>`;}).join(''):'<p style="font-size:12px;margin-top:12px">Alle Aufgaben dieser Einheit wurden richtig beantwortet.</p>'}</section><p class="storage-note" style="margin-top:20px">XP werden je Frage auf insgesamt 20 begrenzt. Erste richtige Antwort im ersten Versuch: 10 XP, danach jeweils 5 XP bis zur Grenze. Wiederholte identische Aufgaben erhöhen nicht die Anzahl verschiedener geprüfter Aufgaben.</p>${examNote()}`;}
function achievements(){const c=computed;const badges=[['Erster Schritt','Schließe deine erste Trainingseinheit ab.',state.sessions.length>=1,'flag','1 abgeschlossene Einheit'],['Entdeckerin','Bearbeite Aufgaben aus allen drei Gebieten.',D.every(d=>Q.some(q=>q.domain===d.id&&c.histories[q.id]?.attempts>0)),'tree','Alle 3 Gebiete erkundet'],['Wissensfunke','Sammle deine ersten 100 XP.',c.xp>=100,'zap','100 XP'],['Dranbleiberin','Schließe 5 Trainingseinheiten ab.',state.sessions.length>=5,'flame','5 abgeschlossene Einheiten'],['Sicheres Fundament','Erreiche eine sichere Kompetenz.',skills.some(s=>c.competency[s.id].status==='secure'),'shield','1 sichere Kompetenz'],['Mathe-Legende','Erreiche Level 60.',c.level>=60,'trophy','2.950 XP'],['Weltenbezwingerin','Erobere alle 30 Länder und bestehe die Zitadelle.',conquest().cleared,'trophy','Alle 31 Gebiete erobert']];return `${heading('Kleine Siege. Große Motivation.','Deine Erfolge machen sichtbar, wie weit du schon gekommen bist.')}<div class="badge-grid">${badges.map(([title,desc,unlocked,ic,condition])=>`<section class="panel badge-card ${unlocked?'unlocked':''}"><div class="badge-medal">${icon(ic==='flag'?'target':ic)}</div><h3>${title}</h3><p>${desc}</p><small>${unlocked?'✦ Freigeschaltet':condition}</small></section>`).join('')}</div>${examNote()}`;}
function progress(){const c=computed;return `${heading('Dein Fortschritt wird sichtbar.','Jede abgeschlossene Einheit ist ein Stück mehr Sicherheit.')} ${stats()}<div class="section-heading"><div><h2>Persönliche Bestleistungen</h2><p>Beste Quote je Gebiet in einer abgeschlossenen Einheit.</p></div></div><div class="best-grid">${D.map(d=>{const values=state.sessions.filter(s=>s.mode==='domain'&&s.ids.every(id=>questionById[id].domain===d.id)).map(s=>percent(c.reports[s.id].score,s.ids.length));return `<div class="stat"><div class="stat-label">${d.name}</div><div class="stat-value">${values.length?Math.max(...values)+' %':'–'}</div><div class="stat-caption">${values.length?values.length+' Gebietstrainings':'Noch kein Gebietstraining'}</div></div>`;}).join('')}</div><section class="panel"><div class="panel-heading"><h2>Deine Trainingseinheiten</h2><span class="muted" style="font-size:10px">${state.sessions.length} abgeschlossen</span></div>${state.sessions.length?[...state.sessions].reverse().map(s=>`<div class="history-row">${icon('check')}<div><strong>${esc(s.title)}</strong><small>${date(s.date)} · ${c.reports[s.id].score}/${s.ids.length} richtig · +${c.reports[s.id].xp} XP</small></div><span class="status">${percent(c.reports[s.id].score,s.ids.length)} %</span><a class="btn btn-ghost" href="#report/${s.id}">Bericht ${icon('arrow')}</a></div>`).join(''):`<div class="empty-state">${icon('chart')}<h3>Hier beginnt deine Geschichte.</h3><p>Deine abgeschlossenen Trainings, Ergebnisse und Bestleistungen erscheinen hier.</p><a class="btn btn-primary" href="#training">Erstes Training starten ${icon('arrow')}</a></div>`}</section><section class="panel" style="margin-top:20px"><h2>Kompetenzmatrix</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Kompetenzbereich</th><th>Verschiedene Aufgaben</th><th>Richtig / Versuche</th><th>Quote</th><th>Status</th><th>Wiederholen</th></tr></thead><tbody>${skills.map(s=>{const x=c.competency[s.id];return `<tr><td>${s.name}<small class="muted" style="display:block;font-size:9px">${domainById[s.domain].name}</small></td><td>${x.unique}/5</td><td>${x.hits}/${x.attempts}</td><td>${x.attempts?x.rate+' %':'–'}</td><td>${statusBadge(x.status)}</td><td>${x.status==='secure'?'Festigen':x.status==='untested'?'Zuerst prüfen':'Empfohlen'}</td></tr>`;}).join('')}</tbody></table></div></section><div class="button-row">${button(`${icon('down')}Lernstand exportieren`,'export-all')}${button('Drucken / PDF','print')}</div>${examNote()}`;}
function solutionMarkup(q){const a=window.MQ_SOLUTIONS[q.id];return `<details class="solution-item"><summary><span>${q.id}</span>${esc(q.prompt)}</summary><div class="solution-body"><h4>Richtige Antwort</h4><div class="solution-answer">${esc(q.options[a.correct])}</div><h4>Erklärung</h4><p>${esc(a.explanation)}</p><h4>Schritt für Schritt</h4><ol>${a.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><h4>Mathematischer Hintergrund</h4><p>${esc(a.background)}</p><h4>Typischer Denkfehler</h4><p>${esc(a.misconception)}</p><h4 class="oral-label">Zum Laut-Erklären</h4><p>${esc(a.oral)}</p><div class="teacher-field"><label for="oral-${q.id}">Einschätzung der Lehrkraft: Konnte die Schülerin ihre Antwort mathematisch begründen?</label><select id="oral-${q.id}" data-oral="${q.id}"><option value="">Noch nicht bewertet</option><option value="yes" ${state.oral[q.id]==='yes'?'selected':''}>Ja</option><option value="partial" ${state.oral[q.id]==='partial'?'selected':''}>Teilweise</option><option value="no" ${state.oral[q.id]==='no'?'selected':''}>Nein</option></select></div></div></details>`;}
function solutions(){if(!solutionsOpen)return `${heading('Verstehen statt nur ankreuzen.','Erklärungen, Lösungswege und Fragen für das mündliche Gespräch.')}<section class="panel empty-state">${icon('book')}<h3>Gemeinsam den nächsten Schritt gehen.</h3><p>Die Lösungen werden nach Freigabe durch die Lehrkraft für diese Sitzung geöffnet. Im laufenden Quiz bleiben sie geschlossen.</p>${button('Lernmodus freigeben','unlock-solutions','btn-primary')}</section><div class="info-box">Die Freigabe ist eine pädagogische Vereinbarung, kein technischer Zugriffsschutz. Fragen und Lösungen liegen in getrennten Dateien; auf einem lokalen Gerät bleibt die Lösungsdatei einsehbar.</div>`;
 const pool=Q.filter(q=>(solutionFilter==='all'||q.domain===solutionFilter)&&(!solutionSearch||`${q.prompt} ${skillById[q.skill].name}`.toLocaleLowerCase('de').includes(solutionSearch.toLocaleLowerCase('de'))));
 return `${heading('Wissen, warum.','Lies nach, rechne mit und erkläre die Idee in deinen eigenen Worten.',button('Freigabe schließen','lock-solutions','btn-ghost'))}<div class="solutions-controls"><select id="solution-domain" aria-label="Lösungen nach Fachgebiet filtern"><option value="all">Alle Wissensgebiete</option>${D.map(d=>`<option value="${d.id}" ${solutionFilter===d.id?'selected':''}>${d.name}</option>`).join('')}</select><input class="search-input" type="search" id="solution-search" aria-label="Aufgaben durchsuchen" placeholder="Aufgabe oder Kompetenz suchen …" value="${esc(solutionSearch)}"></div><p class="storage-note">${pool.length} Aufgaben · Mündliche Bewertungen werden getrennt von Multiple Choice gespeichert.</p><div id="solution-list">${pool.length?pool.map(solutionMarkup).join(''):'<p>Keine passende Aufgabe gefunden.</p>'}</div>`;}
function unlock(){if(state.active){showDialog('Zuerst dein Training abschließen',`<p>Während eines laufenden Trainings bleibt die vollständige Lösungssammlung geschlossen. Feedback zur jeweils beantworteten Frage siehst du direkt im Quiz. Schließe es ab oder verwirf es, bevor du in den Lernmodus wechselst.</p><div class="button-row">${button('Zurück zum Training','resume','btn-primary')}${button('Schließen','close-dialog')}</div>`);return;}showDialog('Freigabe durch die Lehrkraft',`<p>Der Lernmodus zeigt korrekte Antworten und Lösungswege. Die Freigabe gilt bis zum Schließen des Lernmodus oder bis zum nächsten Training.</p><label><input type="checkbox" id="teacher-consent">Die Lehrkraft hat die gemeinsame Arbeit mit den Lösungen freigegeben.</label><p class="storage-note" style="margin-top:15px">Dies ist eine lokale, pädagogische Freigabe ohne Identitätsprüfung.</p><div class="button-row">${button('Abbrechen','close-dialog')}${button('Lösungen öffnen','confirm-unlock','btn-primary')}</div>`);}
function settings(){return `${heading('Dein Lernraum. Deine Daten.','Alles läuft lokal. Du entscheidest, was du mitnehmen möchtest.')}<div class="settings-grid"><section class="panel"><div class="quest-icon">${icon('down')}</div><h2>Fortschritt mitnehmen</h2><p>Exportiere deinen vollständigen Lernstand als JSON. Die Datei enthält Einheiten, Antworten, XP-Grundlagen, mündliche Einschätzungen und ein laufendes Training.</p>${button('Lernstand exportieren','export-all','btn-primary')}<p class="storage-note" style="margin:15px 0 0">Auch für ein anderes Gerät oder deine Nachhilfelehrkraft.</p></section><section class="panel"><div class="quest-icon">${icon('book')}</div><h2>Lernstand importieren</h2><p>Wähle einen zuvor exportierten MatheQuest-Lernstand. Die Datei wird zuerst geprüft. Erst nach deiner Bestätigung ersetzt sie den aktuellen Stand.</p>${button('JSON-Datei auswählen','import')}<input type="file" id="import-file" accept="application/json,.json" hidden><p class="storage-note" style="margin:15px 0 0">Aktuell: ${state.sessions.length} Einheiten · ${computed.xp} XP · Level ${computed.level}</p></section><section class="panel"><h2>So funktioniert dein Fortschritt</h2><p>50 XP führen zum nächsten Level. Du startest auf Level 1; bei 2.950 XP erreichst du Level 60. Pro Frage sind insgesamt höchstens 20 XP möglich: 10 für eine richtige Antwort im allerersten Versuch, danach 5 pro richtiger Wiederholung.</p><p>Kompetenz beruht auf verschiedenen Aufgaben, Wiederholung und Trefferquote. Eine einzelne richtige Antwort genügt nicht. Mündliche Begründungen werden separat bewertet.</p></section><section class="panel"><h2>Lokal gespeichert</h2><p>Dein Browser speichert den Lernstand automatisch. Browserdaten löschen, private Fenster und ein Wechsel des Dateipfads können diesen Speicher verändern. Ein regelmäßiger JSON-Export sichert deinen Fortschritt.</p><p>Keine Anmeldung, kein Backend, keine externen Schriftarten oder Netzwerkanfragen. Die Anwendung läuft durch Öffnen der index.html.</p></section></div><section class="panel" style="margin-top:20px"><h2>Neuanfang</h2><p style="font-size:12px;margin:10px 0 15px">Hier kannst du alle MatheQuest-Lerndaten dieses Browsers löschen. Exportiere sie vorher, wenn du sie behalten möchtest.</p>${button('Lernstand zurücksetzen','reset','btn-danger')}</section>${examNote()}`;}
function download(data,filename){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Deine JSON-Datei wurde zum Download bereitgestellt.');}
function exportAll(){download({...state,exportedAt:new Date().toISOString()},`MatheQuest-Lernstand-${new Date().toISOString().slice(0,10)}.json`);}
async function importFile(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('Die Datei ist zu groß (maximal 5 MB).');const raw=JSON.parse(await file.text());if(raw.kind==='report')throw Error('Dies ist ein einzelner Ergebnisbericht. Bitte wähle einen vollständigen Lernstand aus „Einstellungen & Daten“.');pendingImport=validate(raw);await loadSolutions();showDialog('Lernstand ersetzen?',`<p>Die Datei enthält ${pendingImport.sessions.length} abgeschlossene Einheiten${pendingImport.active?' und ein laufendes Training':''}. Der aktuelle Lernstand wird ersetzt.</p><p>Exportiere deinen bisherigen Lernstand zuerst, wenn du ihn behalten möchtest.</p><div class="button-row">${button('Bisherigen Stand exportieren','export-all')}${button('Abbrechen','close-dialog')}${button('Importieren & ersetzen','confirm-import','btn-primary')}</div>`);}catch(e){pendingImport=null;toast(e instanceof SyntaxError?'Die Datei enthält kein gültiges JSON.':e.message);}}
const routes={dashboard,training,skills:skillMap,progress,achievements,solutions,settings,quiz};
let renderToken=0;
async function render(){const token=++renderToken;let [page,id]=(location.hash.slice(1)||'dashboard').split('/');if(!labels[page])page='dashboard';if((state.sessions.length||(page==='quiz'&&state.active?.answers.some(answer=>answer!==null)))&&!window.MQ_SOLUTIONS){$('#main').innerHTML='<div class="panel">Dein Lernstand wird geladen …</div>';try{await loadSolutions();if(token!==renderToken)return;}catch(e){$('#main').innerHTML=`<div class="save-warning">${esc(e.message)}</div>`;return;}}refresh();if(page==='solutions'&&state.active)solutionsOpen=false;
 document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===page||(page==='quiz'&&a.dataset.nav==='training')||(page==='report'&&a.dataset.nav==='progress');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#page-label').textContent=labels[page];document.title=`${labels[page]} · MatheQuest`;
 const content=page==='report'?report(id):routes[page]();$('#main').innerHTML=(storageFailed?`<div class="save-warning">${esc(saveError||'Der Browser kann deinen Fortschritt nicht dauerhaft speichern. Bitte exportiere deinen Lernstand als JSON, bevor du die Seite schließt.')}</div>`:'')+content;
 $('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');
}
function rerenderQuiz(focusAnswer){const y=window.scrollY;render();window.scrollTo(0,y);if(focusAnswer!==undefined)$('#answer-feedback')?.focus();}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();const action=el.dataset.action;
 switch(action){
 case 'select-country':{selectedCountry=el.dataset.skill;const y=window.scrollY;render();window.scrollTo(0,y);const country=$(`[data-action="select-country"][data-skill="${selectedCountry}"]`);country?.focus({preventScroll:true});break;}
 case 'start-final':solutionsOpen=false;start('final');break;
 case 'start-diagnostic':solutionsOpen=false;start('diagnostic');break;
 case 'start-domain':solutionsOpen=false;start('domain',el.dataset.domain);break;
 case 'start-skill':solutionsOpen=false;start('skill',el.dataset.skill);break;
 case 'confirm-start':closeDialog();state.active=null;start(el.dataset.mode,el.dataset.value);break;
 case 'resume':closeDialog();location.hash='quiz';render();break;
 case 'show-skill-domain':tabDomain=el.dataset.domain;location.hash='skills';render();break;
 case 'skill-tab':tabDomain=el.dataset.domain;render();break;
 case 'answer':{
  const active=state.active,index=active?.index;
  if(!active||active.answers[index]!==null||loadSolutions.answerBusy)break;
  loadSolutions.answerBusy=true;
  try{await loadSolutions();if(state.active!==active||active.index!==index||active.answers[index]!==null)break;active.answers[index]=Number(el.dataset.answer);save();rerenderQuiz(Number(el.dataset.answer));}
  catch(e){toast(e.message);}finally{loadSolutions.answerBusy=false;}break;
 }
 case 'quiz-prev':if(state.active&&state.active.index>0){state.active.index--;save();render();}break;
 case 'quiz-next':if(state.active&&state.active.index<state.active.ids.length-1){state.active.index++;save();render();}break;
 case 'quiz-jump':if(state.active){state.active.index=Number(el.dataset.index);save();render();}break;
 case 'submit':await submit();break;
 case 'confirm-submit':await submit(true);break;
 case 'close-dialog':pendingImport=null;closeDialog();break;
 case 'unlock-solutions':unlock();break;
 case 'confirm-unlock':if(!$('#teacher-consent')?.checked){toast('Bitte bestätige zuerst die Freigabe durch die Lehrkraft.');break;}try{await loadSolutions();solutionsOpen=true;closeDialog();location.hash='solutions';render();}catch(e){toast(e.message);}break;
 case 'lock-solutions':solutionsOpen=false;render();break;
 case 'export-all':exportAll();break;
 case 'export-report':{const s=state.sessions.find(s=>s.id===el.dataset.session);download({app:'MatheQuest',version:1,kind:'report',exportedAt:new Date().toISOString(),session:s,result:{...computed.reports[s.id],total:s.ids.length,percent:percent(computed.reports[s.id].score,s.ids.length),incorrect:s.ids.filter((qid,i)=>s.answers[i]!==window.MQ_SOLUTIONS[qid].correct),unanswered:s.ids.filter((qid,i)=>s.answers[i]===null),recommendations:Object.entries(computed.reports[s.id].bySkill).filter(([sid,g])=>g.correct<g.total).map(([sid])=>skillById[sid].name)},currentLevel:computed.level,oral:Object.fromEntries(s.ids.filter(id=>state.oral[id]).map(id=>[id,state.oral[id]])),questions:s.ids.map(id=>questionById[id])},`MatheQuest-Bericht-${s.id}.json`);break;}
 case 'print':window.print();break;
 case 'import':$('#import-file').click();break;
 case 'confirm-import':if(pendingImport){state=pendingImport;pendingImport=null;saveError='';solutionsOpen=false;save();refresh();closeDialog();render();toast('Dein Lernstand wurde importiert.');}break;
 case 'reset':showDialog('Wirklich neu beginnen?',`<p>Alle Trainingseinheiten, Antworten, XP und mündlichen Bewertungen dieses Browsers werden gelöscht. Diese Aktion lässt sich nur mit einem exportierten Lernstand rückgängig machen.</p><div class="button-row">${button('Abbrechen','close-dialog')}${button('Alles zurücksetzen','confirm-reset','btn-danger')}</div>`);break;
 case 'confirm-reset':state=fresh();saveError='';solutionsOpen=false;save();refresh();closeDialog();location.hash='dashboard';render();toast('Deine neue Lernreise beginnt auf Level 1.');break;
 }
});
document.addEventListener('keydown',e=>{const country=e.target.closest('.map-country');if(country&&(e.key==='Enter'||e.key===' ')){e.preventDefault();country.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='import-file'){importFile(el.files[0]);el.value='';}if(el.dataset.oral){if(el.value)state.oral[el.dataset.oral]=el.value;else delete state.oral[el.dataset.oral];save();toast('Mündliche Einschätzung gespeichert.');}if(el.id==='solution-domain'){solutionFilter=el.value;render();}});
document.addEventListener('input',event=>{if(event.target.id==='solution-search'){solutionSearch=event.target.value;const pos=event.target.selectionStart;render();const field=$('#solution-search');field?.focus({preventScroll:true});field?.setSelectionRange(pos,pos);}});
$('#menu-button').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String(open));});
document.addEventListener('click',e=>{if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-button')){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>{closeDialog();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY)toast('Der Lernstand wurde in einem anderen Tab geändert. Lade diese Seite neu, bevor du weiterübst.');});
render();
})();
